\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $\Gamma$ be a type $\mathrm{II}_1$ factor with faithful trace $\tau$, and let $T\in\Gamma$ have Brown measure $\mu_T=\delta_0$. Must there exist a projection $P\in\Gamma$, $0<P<1$, whose range is invariant under $T$, equivalently $(1-P)TP=0$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://aimath.org/WWN/freeanalysis/freeanalysis.pdf}{[S2]}.

\subsection{Short English statement}
Let $\Gamma$ be a type $\mathrm{II}_1$ factor with faithful trace $\tau$, and let $T\in\Gamma$ have Brown measure $\mu_T=\delta_0$. Must there exist a projection $P\in\Gamma$, $0<P<1$, whose range is invariant under $T$, equivalently $(1-P)TP=0$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 20002687 (AIM-PROBABILITY-0129). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
